SELECT *, SUM(DISTINCT CHAR_LENGTH(x10.Name_exp_1)), SUM(x10.Name_exp_1), SUM(DISTINCT x10.Name_exp_1), SUM(FLOOR(x10.Name_exp_1 / 20) * (x10.Name_exp_1 % 20)), SUM(RANK() OVER (ORDER BY x10.Name_exp_1)), SUM(LEAST(x10.Name_exp_1, x10.Name_exp_1)), SUM(LEAST(x10.Name_exp_1, x10.Name_exp_1)), SUM(1.2), SUM(DISTINCT SUBSTRING('x', 1, 3)) FROM v48702 AS x10 GROUP BY x10.Name_exp_1 COLLATE ucs2_spanish2_ci